std::string StringToLower(std::string str) {
    for (char &c : str) {
        c = std::tolower(c);
    }
    return str;
}

std::string StringToUpper(std::string str) {
    for (char &c : str) {
        c = std::toupper(c);
    }
    return str;
}

std::string ReplaceAllSubstring(std::string_view str, std::string_view from, std::string_view to) {
    std::string result = std::string(str);
    size_t pos = 0;
    while ((pos = result.find(from, pos)) != std::string::npos) {
        result.replace(pos, from.length(), to);
        pos += to.length();
    }
    return result;
}

std::vector<std::string> SplitString(const std::string& str, const std::regex& pattern) {
    std::vector<std::string> result;
    std::sregex_token_iterator it(str.begin(), str.end(), pattern, -1);
    std::sregex_token_iterator end;
    while (it != end) {
        result.push_back(*it++);
    }
    return result;
}

std::vector<std::string> SplitStringToLines(const std::string& str) {
    std::vector<std::string> result;
    std::string line;
    for (char c : str) {
        if (c == '\n') {
            result.push_back(line);
            line = "";
        } else {
            line += c;
        }
    }
    result.push_back(line);
    return result;
}

YAML::Node LoadYamlString(std::string_view str, std::initializer_list<std::string_view> required_fields) {
    YAML::Node node = YAML::Load(str);
    for (const auto& field : required_fields) {
        if (!node.Contains(field)) {
            throw std::runtime_error("Required field '" + std::string(field) + "' not found in YAML.");
        }
    }
    return node;
}

void ThrowIfYamlFieldIsNotScalar(const YAML::Node& node, std::string_view field) {
    if (!node[field].IsScalar()) {
        throw std::runtime_error("YAML field '" + std::string(field) + "' is not a scalar.");
    }
}

