class MappedReadOnlyFile {
public:
    MappedReadOnlyFile() noexcept : path_(""), stat_{}, data_(nullptr) {}
    MappedReadOnlyFile(MappedReadOnlyFile&& other) noexcept : path_(std::move(other.path_)), stat_(other.stat_), data_(other.data_) {
        other.data_ = nullptr;
    }
    ~MappedReadOnlyFile() noexcept {
        Unmap();
    }

    std::byte* Map(std::string path) {
        if (Check(path)) {
            int fd = open(path_.c_str(), O_RDONLY);
            if (fd == -1) {
                throw std::runtime_error("Failed to open file: " + path);
            }

            data_ = static_cast<std::byte*>(mmap(nullptr, stat_.st_size, PROT_READ, MAP_PRIVATE, fd, 0));
            if (data_ == MAP_FAILED) {
                close(fd);
                throw std::runtime_error("Failed to map file: " + path);
            }
            path_ = path;
            return data_;
        } else {
            return nullptr;
        }
    }

    void Unmap() noexcept {
        if (data_) {
            munmap(data_, stat_.st_size);
            data_ = nullptr;
        }
    }

    std::size_t Size() const noexcept {
        return stat_.st_size;
    }

    std::byte* Data() const noexcept {
        return data_;
    }

    std::string_view Path() const noexcept {
        return path_;
    }

private:
    bool Check(const std::string& path) {
        if (stat(path.c_str(), &stat_) == 0) {
            return true;
        } else {
            return false;
        }
    }

    std::string path_; 
    struct stat stat_; 
    std::byte* data_; 
};

